package ec.edu.unl.sec.selfassessment.infrastructure;
import com.fasterxml.jackson.core.*;import com.fasterxml.jackson.databind.*;import ec.edu.unl.sec.selfassessment.application.*;import ec.edu.unl.sec.selfassessment.domain.*;import java.sql.*;import java.time.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;
@Repository public class JdbcSelfAssessmentRepository implements SelfAssessmentRepository{private final JdbcTemplate jdbc;private final ObjectMapper json;public JdbcSelfAssessmentRepository(JdbcTemplate jdbc,ObjectMapper json){this.jdbc=jdbc;this.json=json;}public void save(SelfAssessmentProcess p,long expected){if(expected<0){jdbc.update("insert into self_assessment_process(id,career_id,code,name,period_start,period_end,model_version_id,model_version_number,state,revision,created_by,created_at,snapshot_json) values(?,?,?,?,?,?,?,?,?,?,?,?,?::jsonb)",p.id(),p.careerId(),p.code(),p.name(),p.periodStart(),p.periodEnd(),p.modelVersionId(),p.modelVersionNumber(),p.state().name(),p.revision(),p.createdBy(),Timestamp.from(p.createdAt()),encode(p));}else{int n=jdbc.update("update self_assessment_process set state=?,revision=?,snapshot_json=?::jsonb where id=? and revision=?",p.state().name(),p.revision(),encode(p),p.id(),expected);if(n!=1)throw new IllegalStateException("STALE_PROCESS");if(p.state()==ProcessState.ACTIVE&&expected==0){for(var i:p.indicators())jdbc.update("insert into process_indicator(process_id,indicator_id,code,name) values(?,?,?,?) on conflict do nothing",p.id(),i.id(),i.code(),i.name());}}}public Optional<SelfAssessmentProcess> find(UUID id){return jdbc.query("select snapshot_json::text from self_assessment_process where id=?",(r,n)->decode(r.getString(1)),id).stream().findFirst();}public List<SelfAssessmentProcess> list(){return jdbc.query("select snapshot_json::text from self_assessment_process order by created_at desc",(r,n)->decode(r.getString(1)));}public void saveAssignment(ProcessAssignment a){jdbc.update("insert into process_assignment(id,process_id,indicator_id,identity_id,function_code,valid_from,valid_to,created_by,reason,revoked_at,revision) values(?,?,?,?,?,?,?,?,?,?,?)",a.id(),a.processId(),a.indicatorId(),a.identityId(),a.function().name(),Timestamp.from(a.validFrom()),Timestamp.from(a.validTo()),a.createdBy(),a.reason(),a.revokedAt()==null?null:Timestamp.from(a.revokedAt()),a.revision());}public List<ProcessAssignment> assignments(UUID id){return jdbc.query("select id,process_id,indicator_id,identity_id,function_code,valid_from,valid_to,created_by,reason,revoked_at,revision from process_assignment where process_id=? order by valid_from",(r,n)->new ProcessAssignment(r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getObject(3,UUID.class),r.getObject(4,UUID.class),ProcessAssignment.Function.valueOf(r.getString(5)),r.getTimestamp(6).toInstant(),r.getTimestamp(7).toInstant(),r.getObject(8,UUID.class),r.getString(9),r.getTimestamp(10)==null?null:r.getTimestamp(10).toInstant(),r.getLong(11)),id);}public void recordTransition(UUID id,ProcessState from,ProcessState to,UUID actor,String reason,UUID correlation,long revision){jdbc.update("insert into process_transition(id,process_id,from_state,to_state,actor_id,reason,occurred_at,correlation_id,resulting_revision) values(?,?,?,?,?,?,?,?,?)",UUID.randomUUID(),id,from.name(),to.name(),actor,reason==null?"":reason,Timestamp.from(Instant.now()),correlation,revision);if(to==ProcessState.CLOSED)jdbc.update("insert into process_closure(id,process_id,closed_at,closed_by) values(?,?,?,?)",UUID.randomUUID(),id,Timestamp.from(Instant.now()),actor);if(to==ProcessState.REOPENED)jdbc.update("update process_closure set reopened_at=?,reopened_by=?,reopen_reason=? where process_id=? and reopened_at is null",Timestamp.from(Instant.now()),actor,reason,id);}private String encode(SelfAssessmentProcess p){try{return json.writeValueAsString(p);}catch(JsonProcessingException e){throw new IllegalStateException(e);}}private SelfAssessmentProcess decode(String s){try{return json.readValue(s,SelfAssessmentProcess.class);}catch(JsonProcessingException e){throw new IllegalStateException(e);}}}
